{"path": "parser.mjs", "content": "const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseIntegerField(raw, fieldName, rowNumber, { allowZero }) {
  if (!DIGITS_PATTERN.test(raw)) {
    throw new Error(
      `Row ${rowNumber}: ${fieldName} must be base-10 digits, got ${JSON.stringify(raw)}`
    );
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(
      `Row ${rowNumber}: ${fieldName} exceeds Number.MAX_SAFE_INTEGER`
    );
  }
  if (!allowZero && value === 0) {
    throw new Error(`Row ${rowNumber}: ${fieldName} must be positive`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }

  const orders = [];
  const lines = text.split('\n');

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === '') {
      continue;
    }

    const rowNumber = index + 1;
    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Row ${rowNumber}: expected exactly 3 fields, got ${fields.length}`);
    }

    const sku = fields[0].trim();
    const quantityRaw = fields[1].trim();
    const unitPriceRaw = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Row ${rowNumber}: invalid SKU ${JSON.stringify(sku)}`);
    }

    const quantity = parseIntegerField(quantityRaw, 'quantity', rowNumber, {
      allowZero: false,
    });
    const unitPriceCents = parseIntegerField(unitPriceRaw, 'unitPriceCents', rowNumber, {
      allowZero: true,
    });

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}
"}

